import { timeInMs } from '../../../../../../shared';
import cachedFetch from '../../../../../../shared/cachedFetch';

const TENOR_API_KEY = '6VES18TSQYAW';

interface MediaResponse {
  url: string
  dims: [number, number],
  duration: number,
  preview: string
  size: number
}

export interface TenorGifsResponse {
  weburl: string,
  next: string,
  results: {
    tags: string[],
    url: string,
    created: number,
    shares: number,
    itemurl: string,
    // composite: null,
    hasaudio: boolean,
    title: string,
    id: string,
    media: Record<string, MediaResponse>[],
  }[],
}

const fetchTenor = async <T>(path: string, query?: Record<string, unknown>, skipCache?: boolean): Promise<T> => {
  const url = `https://api.tenor.com/v1${path}?${new URLSearchParams({
    ...query,
    media_filter: 'basic',
    key: TENOR_API_KEY
  })}`;

  return cachedFetch<T>(url, timeInMs.day, skipCache);
};

export default fetchTenor;
