import { useState } from 'preact/hooks';

import Button from '../../../../../shared/Button';
import GifPreview from '../../shared/GifPreview';

import styles from './styles.module.scss';
import { FunctionalComponent } from 'preact';

interface DataProp {
  message: any,
  media: any
}

interface Props {
  onSubmit: (data: { message: string }) => unknown;
  data: DataProp;
}

const Preview: FunctionalComponent<Props> = ({ data, onSubmit }: Props) => {
  const [message, setMessage] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();
    onSubmit({ message });
  };

  const handleChange = (evt) => {
    setMessage(evt.target.value);
  };

  return (
    <>
      <div className={styles.gifPreview}>
        <GifPreview
          message={{
            imgSrc: data.media[0].tinymp4.url,
            message,
          }}
        />
      </div>

      <footer>
        <form onSubmit={handleSubmit}>
          <div className={styles.textInput}>
            <label htmlFor="name">Add text (optional)</label>
            <textarea name="name" value={message} onChange={handleChange} />
          </div>

          <div className={styles.buttonsFooter}>
            <Button size="large" type="submit" variant="primary">
              Send
            </Button>
          </div>
        </form>
      </footer>
    </>
  );
};

export default Preview;
